                                Err(e) => {
                                    let msg = e.to_string();
                                    chat_span.record("otel.status_code", "ERROR");
                                    run_span.record("otel.status_code", "ERROR");
                                    failure.set(crate::AgentError::Model(e));
                                    yield crate::AgentEvent::RunFailed { error: msg };
